function iniciarSincronizacaoCases() {
    const logoItems = document.querySelectorAll('#cases-logo .jet-listing-grid__item');
    const caseContent = document.querySelector('#case-content .jet-listing-grid__slider');

    if (logoItems.length === 0 || !caseContent) {
        // Ainda não carregou o conteúdo, aguarda e tenta de novo
        setTimeout(iniciarSincronizacaoCases, 200);
        return;
    }

    // Numera os logos
    logoItems.forEach((item, index) => {
        item.setAttribute('data-index', index);
    });

    logoItems.forEach(logo => {
        logo.addEventListener('click', function () {
            const index = parseInt(logo.getAttribute('data-index'));

            if ($(caseContent).hasClass('slick-initialized')) {
                $(caseContent).slick('slickGoTo', index);
            }

            // Marcar o logo ativo
            logoItems.forEach(item => item.classList.remove('ativo'));
            logo.classList.add('ativo');
        });
    });

    // Já pode marcar o primeiro como ativo inicialmente
    logoItems[0].classList.add('ativo');
}

// Dispara quando o DOM já estiver carregado
document.addEventListener('DOMContentLoaded', iniciarSincronizacaoCases);
